class Solution:
    def distMoney(self, money: int, children: int) -> int:
        def ok(c):
            r = children - c
            tot = money - 8 * c
            if tot < r:
                return False
            e = tot - r
            if r == 0:
                return e == 0
            if r == 1:
                return e != 3
            return True
        for c in range(children, -1, -1):
            if ok(c):
                return c
        return -1

