            if (tot < r) return false;
            int e = tot - r;
            if (r == 0) return e == 0;
            if (r == 1) return e != 3;
            return true;
        };
        for (int c = children; c >= 0; --c)
            if (ok(c)) return c;
        return -1;
    }
};

