class Solution:
    def distMoney(self, money: int, children: int) -> int:
        if money < children:
            return -1
        rem = money - children
        k = min(rem // 7, children)
        left = rem - 7 * k
        if k == children:
            return children - 1 if left > 0 else children
        if left == 3 and children - k == 1:
            return k - 1
        return k

